namespace fs=std::filesystem;
using Clock=std::chrono::steady_clock;
static void require(bool v,const std::string&m){if(!v)throw std::runtime_error(m);}
static std::vector<char> readFile(const fs::path&p){std::ifstream f(p,std::ios::binary);require(bool(f),"cannot read "+p.string());return {std::istreambuf_iterator<char>(f),{}};}
static std::string hashBytes(const void*p,size_t n){unsigned char h[CC_SHA256_DIGEST_LENGTH];require(n<=UINT32_MAX,"SHA input too large");CC_SHA256(p,(CC_LONG)n,h);std::ostringstream s;for(auto c:h)s<<std::hex<<std::setw(2)<<std::setfill('0')<<int(c);return s.str();}
static std::string hashFile(const fs::path&p){auto b=readFile(p);return hashBytes(b.data(),b.size());}
static void json(const fs::path&p,id v){fs::create_directories(p.parent_path());NSError*e=nil;auto d=[NSJSONSerialization dataWithJSONObject:v options:NSJSONWritingPrettyPrinted error:&e];require(d,e.localizedDescription.UTF8String?:"JSON serialization");require([d writeToFile:@(p.string().c_str()) atomically:YES],"JSON write "+p.string());}
static NSDictionary* readJSON(const fs::path&p){auto d=[NSData dataWithContentsOfFile:@(p.string().c_str())];require(d,"missing JSON "+p.string());NSError*e=nil;id o=[NSJSONSerialization JSONObjectWithData:d options:0 error:&e];require([o isKindOfClass:NSDictionary.class],e.localizedDescription.UTF8String?:"JSON root type");return o;}
static id<MTLBuffer> load(id<MTLDevice>d,const fs::path&p,size_t n){auto b=readFile(p);require(b.size()==n,"size mismatch "+p.string());auto r=[d newBufferWithBytes:b.data() length:n options:MTLResourceStorageModeShared];require(r,"input allocation");return r;}
static id<MTLBuffer> output(id<MTLDevice>d,size_t n){auto b=[d newBufferWithLength:n*4 options:MTLResourceStorageModeShared];require(b,"output allocation");std::fill_n((float*)b.contents,n,NAN);return b;}
static void save(const fs::path&p,id<MTLBuffer>b){fs::create_directories(p.parent_path());std::ofstream f(p,std::ios::binary);f.write((const char*)b.contents,b.length);require(bool(f),"write "+p.string());}
static bool finite(id<MTLBuffer>b){auto p=(const float*)b.contents;for(size_t i=0;i<b.length/4;++i)if(!std::isfinite(p[i]))return false;return true;}
static std::vector<char> bytes(id<MTLBuffer>b){auto p=(const char*)b.contents;return {p,p+b.length};}
static std::string thermal(){switch(NSProcessInfo.processInfo.thermalState){case NSProcessInfoThermalStateNominal:return "nominal";case NSProcessInfoThermalStateFair:return "fair";case NSProcessInfoThermalStateSerious:return "serious";case NSProcessInfoThermalStateCritical:return "critical";}return "unknown";}
static double us(Clock::time_point a){return std::chrono::duration<double,std::micro>(Clock::now()-a).count();}
static void complete(id<MTLCommandBuffer>c){[c commit];[c waitUntilCompleted];require(c.status==MTLCommandBufferStatusCompleted,c.error.localizedDescription.UTF8String?:"GPU command failed");}
static id<MTLComputePipelineState> pipeline(id<MTLDevice>d,const fs::path&p,NSString*n){NSError*e=nil;auto l=[d newLibraryWithURL:[NSURL fileURLWithPath:@(p.string().c_str())] error:&e];require(l,e.localizedDescription.UTF8String?:"load metallib");auto f=[l newFunctionWithName:n];require(f,"missing symbol "+std::string(n.UTF8String));auto r=[d newComputePipelineStateWithFunction:f error:&e];require(r,e.localizedDescription.UTF8String?:"create pipeline");return r;}
struct Inputs {
 id<MTLBuffer>wg,wu,wd,gamma,x;
 Inputs(id<MTLDevice>d,const fs::path&root,int step,int layer=0){auto w=root/"weights"/("layer-"+std::to_string(layer)),v=root/("step-"+std::to_string(step))/("layer-"+std::to_string(layer));wg=load(d,w/"ffn_gate.tq2",4561920);wu=load(d,w/"ffn_up.tq2",4561920);wd=load(d,w/"ffn_down.tq2",4561920);gamma=load(d,w/"subnorm.f32",27648);x=load(d,v/"x.f32",10240);}
};
struct Buffers {
 id<MTLBuffer>gate,up,relu,square,activation,norm,down,rawGate,rawUp;
 Buffers(id<MTLDevice>d,bool separate=false){gate=output(d,6912);up=output(d,6912);relu=output(d,6912);square=output(d,6912);activation=separate?output(d,6912):gate;norm=separate?output(d,6912):up;down=output(d,2560);rawGate=output(d,6912);rawUp=output(d,6912);}
 std::map<std::string,id<MTLBuffer>> outputs(){return {{"activation",activation},{"down-input",norm},{"down",down}};}
};
class Engine {
 StockFFN stock_; id<MTLComputePipelineState>dual_,post_,copy_,k_,old_,f8_,split_,splitPost_;
 static void custom(ggml_metal_encoder_t e,id<MTLComputePipelineState>p,std::initializer_list<id<MTLBuffer>>b,MTLSize g,MTLSize t){auto raw=(__bridge id<MTLComputeCommandEncoder>)ggml_metal_encoder_get_obj(e);[raw setComputePipelineState:p];NSUInteger j=0;for(auto v:b)[raw setBuffer:v offset:0 atIndex:j++];[raw dispatchThreadgroups:g threadsPerThreadgroup:t];}
 void copyRaw(ggml_metal_encoder_t e,Buffers&b,bool probe){if(probe){ggml_metal_encoder_memory_barrier(e);custom(e,copy_,{b.gate,b.rawGate},MTLSizeMake(27,1,1),MTLSizeMake(256,1,1));custom(e,copy_,{b.up,b.rawUp},MTLSizeMake(27,1,1),MTLSizeMake(256,1,1));ggml_metal_encoder_memory_barrier(e);}}
public:
 explicit Engine(const fs::path&s){auto d=stock_.device();dual_=pipeline(d,s/"ffn-mechanisms.metallib",@"ffn_dual_projection");post_=pipeline(d,s/"ffn-mechanisms.metallib",@"ffn_post_strict");copy_=pipeline(d,s/"ffn-mechanisms.metallib",@"ffn_shadow_copy");k_=pipeline(d,s/"k0-postnorm-inplace.metallib",@"ffn_post_weighted_norm_inplace");old_=pipeline(d,s/"k0-postnorm-reference.metallib",@"ffn_post_weighted_norm");f8_=pipeline(d,s/"ffn-gate-up-8x2.metallib",@"tq2_0_matvec_ffn_gate_up_8x2");split_=pipeline(d,s/"ffn-expand.metallib",@"tq2_0_matvec_ffn_expand");splitPost_=pipeline(d,s/"ffn-gate-up-8x2.metallib",@"ffn_relu2_mul");
  for(auto p:{dual_,post_,copy_,k_,old_,f8_,split_,splitPost_})require(p.threadExecutionWidth==32,"SIMD width changed");for(auto p:{dual_,f8_,split_})require(p.maxTotalThreadsPerThreadgroup>=64,"projection thread limit");for(auto p:{post_,copy_,splitPost_})require(p.maxTotalThreadsPerThreadgroup>=256,"post thread limit");for(auto p:{k_,old_})require(p.maxTotalThreadsPerThreadgroup>=1024&&p.staticThreadgroupMemoryLength==27776&&p.staticThreadgroupMemoryLength<=d.maxThreadgroupMemoryLength,"postnorm resource contract unsupported");require(stock_.normThreads()==1024,"stock norm geometry changed");
 }
 id<MTLDevice>device(){return stock_.device();}id<MTLCommandQueue>queue(){return stock_.queue();}
 int count(const std::string&r){if(r=="S")return 7;if(r=="G")return 4;if(r=="K"||r=="Kref"||r=="F8")return 3;if(r=="F8ref")return 5;throw std::runtime_error("unknown route");}
 NSDictionary* metadata(){NSMutableDictionary*m=[stock_.metadata()mutableCopy];m[@"alias_layout"]=@"S/G/K/F8 Gate=activation and Up=norm; reference K0 uses disjoint outputs";m[@"timing_scope"]=@"standalone whole FFN on same captured W/X, one serial encoder/CB; not model decode";m[@"device_max_tg_bytes"]=@(device().maxThreadgroupMemoryLength);NSMutableDictionary*p=[NSMutableDictionary dictionary];for(auto v:std::vector<std::pair<std::string,id<MTLComputePipelineState>>>{{"dual",dual_},{"post",post_},{"K",k_},{"Kref",old_},{"F8",f8_},{"split",split_}})p[@(v.first.c_str())]=@{@"label":v.second.label?:@"",@"SIMD":@(v.second.threadExecutionWidth),@"max_threads":@(v.second.maxTotalThreadsPerThreadgroup),@"static_tg_bytes":@(v.second.staticThreadgroupMemoryLength)};m[@"actual_custom_pipelines"]=p;return m;}
 void encode(id<MTLCommandBuffer>c,const std::string&r,Inputs&i,Buffers&b,bool probe){(void)count(r);auto e=ggml_metal_encoder_init((__bridge void*)c,false);require(e,"encoder init");
  if(r=="S"){stock_.gate(e,i.wg,i.x,b.gate);stock_.relu(e,b.gate,b.relu);stock_.up(e,i.wu,i.x,b.up);copyRaw(e,b,probe);stock_.square(e,b.relu,b.square);stock_.multiply(e,b.square,b.up,b.activation);}
  else if(r=="G"||r=="K"||r=="Kref"){custom(e,dual_,{i.wg,i.wu,i.x,b.gate,b.up},MTLSizeMake(864,1,2),MTLSizeMake(32,2,1));copyRaw(e,b,probe);ggml_metal_encoder_memory_barrier(e);if(r=="G")custom(e,post_,{b.gate,b.up,b.activation},MTLSizeMake(27,1,1),MTLSizeMake(256,1,1));else if(r=="K")custom(e,k_,{b.gate,b.up,i.gamma},MTLSizeMake(1,1,1),MTLSizeMake(1024,1,1));else custom(e,old_,{b.gate,b.up,i.gamma,b.activation,b.norm},MTLSizeMake(1,1,1),MTLSizeMake(1024,1,1));}
  else if(r=="F8")custom(e,f8_,{i.wg,i.wu,i.x,b.activation},MTLSizeMake(432,1,1),MTLSizeMake(32,2,1));
  else{custom(e,split_,{i.wg,i.x,b.gate},MTLSizeMake(432,1,1),MTLSizeMake(32,2,1));custom(e,split_,{i.wu,i.x,b.up},MTLSizeMake(432,1,1),MTLSizeMake(32,2,1));copyRaw(e,b,probe);ggml_metal_encoder_memory_barrier(e);custom(e,splitPost_,{b.gate,b.up,b.activation},MTLSizeMake(27,1,1),MTLSizeMake(256,1,1));}
  ggml_metal_encoder_memory_barrier(e);if(r!="K"&&r!="Kref"){stock_.norm(e,b.activation,i.gamma,b.norm);ggml_metal_encoder_memory_barrier(e);}stock_.down(e,i.wd,b.norm,b.down);ggml_metal_encoder_end_encoding(e);ggml_metal_encoder_free(e);
 }
};
static NSDictionary* metrics(id<MTLBuffer>a,id<MTLBuffer>b){require(a.length==b.length,"metric sizes");size_t bits=0,fail=0,nan=0;double max=0,se=0,sr=0,ratio=0;const auto*x=(const float*)a.contents,*y=(const float*)b.contents;for(size_t j=0;j<a.length/4;++j){bits+=std::memcmp(x+j,y+j,4)!=0;double e=std::abs(double(x[j])-y[j]),t=2e-4+2e-5*std::abs(double(y[j]));bool f=std::isfinite(x[j])&&std::isfinite(y[j]);nan+=!f;fail+=!f||e>t;max=std::max(max,e);ratio=std::max(ratio,e/t);se+=e*e;sr+=double(y[j])*y[j];}return @{@"rows":@(a.length/4),@"different_bits_rows":@(bits),@"failed_rows":@(fail),@"nonfinite_rows":@(nan),@"max_abs":@(max),@"max_error_over_tolerance":@(ratio),@"relative_l2":@(sr>0?std::sqrt(se/sr):0),@"bitwise_pass":@(bits==0&&nan==0)};}
static NSDictionary* local64(id<MTLBuffer>a,id<MTLBuffer>g,id<MTLBuffer>u,id<MTLBuffer>gamma,bool norm){size_t fail=0;double max=0,se=0,sr=0,ratio=0,sum=0;const auto*y=(float*)a.contents,*x=(float*)g.contents,*v=(float*)u.contents,*gm=(float*)gamma.contents;const size_t n=a.length/4;if(norm)for(size_t j=0;j<n;++j)sum+=double(x[j])*x[j];const double scale=norm?1/std::sqrt(sum/double(n)+1e-5):0;for(size_t j=0;j<n;++j){double pos=std::max(0.0,double(x[j]));double ref=norm?(double(x[j])*scale)*gm[j]:(pos*pos)*v[j];double e=std::abs(double(y[j])-ref),tol=2e-4+2e-5*std::abs(ref);fail+=!std::isfinite(y[j])||!std::isfinite(ref)||e>tol;max=std::max(max,e);ratio=std::max(ratio,e/tol);se+=e*e;sr+=ref*ref;}return @{@"rows":@(n),@"failed_rows":@(fail),@"max_abs":@(max),@"max_error_over_tolerance":@(ratio),@"relative_l2":@(sr>0?std::sqrt(se/sr):0),@"pass":@(fail==0),@"reference":norm?@"FP64 weighted norm from actual F32 activation/gamma":@"FP64 post from actual/reference F32 gate/up"};}
static NSMutableDictionary* identities(const fs::path&f,const fs::path&s){NSMutableDictionary*d=[NSMutableDictionary dictionary];for(auto n:{"ffn_gate.tq2","ffn_up.tq2","ffn_down.tq2","subnorm.f32"}){auto p=f/"weights/layer-0"/n;d[@(p.string().c_str())]=@(hashFile(p).c_str());}for(int step:{1,16,32})for(auto n:{"x.f32","gate.f32","up.f32","activation.f32","down-input.f32","down.f32"}){auto p=f/("step-"+std::to_string(step))/"layer-0"/n;d[@(p.string().c_str())]=@(hashFile(p).c_str());}for(auto n:{"ffn-mechanisms.metallib","k0-postnorm-inplace.metallib","k0-postnorm-reference.metallib","ffn-gate-up-8x2.metallib","ffn-expand.metallib"}){auto p=s/n;d[@(p.string().c_str())]=@(hashFile(p).c_str());}return d;}

static int reference(Engine&e,const fs::path&fixture,const fs::path&shader,const fs::path&out){require(!fs::exists(out),"refuse existing reference output");fs::create_directories(out);std::vector<int>layers;for(const auto&d:fs::directory_iterator(fixture/"weights")){auto name=d.path().filename().string();if(name.rfind("layer-",0)==0&&fs::exists(d.path()/"ffn_gate.tq2")&&fs::exists(d.path()/"ffn_up.tq2")){int layer=std::stoi(name.substr(6));require(layer>=0&&layer<30,"invalid reference layer");layers.push_back(layer);}}std::sort(layers.begin(),layers.end());require(!layers.empty(),"no eligible captured K layers");NSMutableDictionary*hashes=[NSMutableDictionary dictionary];for(auto n:{"ffn-mechanisms.metallib","k0-postnorm-reference.metallib"}){auto p=shader/n;hashes[@(p.string().c_str())]=@(hashFile(p).c_str());}NSMutableArray*records=[NSMutableArray array],*layerList=[NSMutableArray array];bool all=true,local=true;size_t completed=0;
 for(int layer:layers){@autoreleasepool{[layerList addObject:@(layer)];auto w=fixture/"weights"/("layer-"+std::to_string(layer));for(auto name:{"ffn_gate.tq2","ffn_up.tq2","ffn_down.tq2","subnorm.f32"}){auto p=w/name;hashes[@(p.string().c_str())]=@(hashFile(p).c_str());}Inputs in(e.device(),fixture,1,layer);
 for(int step=1;step<=32;++step){@autoreleasepool{auto suffix=fs::path("step-"+std::to_string(step))/("layer-"+std::to_string(layer));auto actual=fixture/suffix;in.x=load(e.device(),actual/"x.f32",10240);for(auto name:{"x.f32","gate.f32","up.f32","activation.f32","down-input.f32","down.f32"}){auto p=actual/name;hashes[@(p.string().c_str())]=@(hashFile(p).c_str());}Buffers b(e.device(),true);auto c=[e.queue()commandBuffer];c.label=@(("A16-K0-independent-reference-layer"+std::to_string(layer)+"-step"+std::to_string(step)).c_str());e.encode(c,"Kref",in,b,false);complete(c);auto dest=out/suffix;NSMutableDictionary*checks=[NSMutableDictionary dictionary];bool sameCase=true;std::map<std::string,id<MTLBuffer>>vectors={{"gate",b.gate},{"up",b.up},{"activation",b.activation},{"down-input",b.norm},{"down",b.down}};for(auto&[name,v]:vectors){require(finite(v),"reference output unwritten/nonfinite "+name);auto ref=load(e.device(),actual/(name+".f32"),v.length);require(finite(ref),"actual graph nonfinite "+name);auto m=metrics(v,ref);checks[@(name.c_str())]=m;sameCase&=[m[@"bitwise_pass"]boolValue];save(dest/(name+".f32"),v);}auto mp=local64(b.activation,b.gate,b.up,in.gamma,false),mn=local64(b.norm,b.activation,b.activation,in.gamma,true);bool localCase=[mp[@"pass"]boolValue]&&[mn[@"pass"]boolValue];all&=sameCase;local&=localCase;++completed;[records addObject:@{@"layer":@(layer),@"step":@(step),@"GPU_completed":@YES,@"command_status":@(c.status),@"dispatches":@3,@"all_rows_bitwise_pass":@(sameCase),@"raw_gate_up_act_norm_down":checks,@"local_post_fp64":mp,@"local_norm_fp64":mn}];}}
 }}json(out/"qualification.json",@{@"local_research_pass":@(all&&local),@"integration_parity_pass":@(all),@"local_post_norm_fp64_pass":@(local),@"full_chain_fp64_pass":[NSNull null],@"model_output_pass":[NSNull null],@"model_quality_tested":@NO,@"CPU_processing_success":@YES,@"layers":layerList,@"expected_cases":@(layers.size()*32),@"completed_cases":@(completed),@"identity_sha256":hashes,@"records":records,@"device":e.device().name,@"pipelines":e.metadata(),@"threshold":@{@"abs":@(2e-4),@"relative":@(2e-5)},@"scope":@"all32actualcapturedKcallsperpositivelayer; independent stock4dual + oldfiveargK0/J + actualstockdown, disjointreferenceoutputs; no performance samples"});return all&&local?0:1;}

static int verify(Engine&e,const fs::path&fixture,const fs::path&shader,const fs::path&out){require(!fs::exists(out),"refuse existing verification output");fs::create_directories(out);auto hashes=identities(fixture,shader);NSMutableArray*cases=[NSMutableArray array];bool all=true;for(int step:{1,16,32}){@autoreleasepool{Inputs in(e.device(),fixture,step);std::map<std::string,std::unique_ptr<Buffers>>b;
 for(auto r:{"S","G","K","Kref","F8","F8ref"}){auto v=std::make_unique<Buffers>(e.device(),std::string(r)=="Kref");auto c=[e.queue()commandBuffer];c.label=@((std::string("operator-verify-clean-")+r+"-step"+std::to_string(step)).c_str());e.encode(c,r,in,*v,false);complete(c);std::map<std::string,std::vector<char>>clean;for(auto&[name,buf]:v->outputs()){require(finite(buf),"unwritten output "+std::string(r)+"/"+name);clean[name]=bytes(buf);}auto p=[e.queue()commandBuffer];p.label=@((std::string("operator-verify-probed-")+r+"-step"+std::to_string(step)).c_str());e.encode(p,r,in,*v,true);complete(p);bool fidelity=true;for(auto&[name,buf]:v->outputs())fidelity&=clean[name]==bytes(buf)&&finite(buf);all&=fidelity;auto dst=out/("step-"+std::to_string(step))/r;for(auto&[name,buf]:v->outputs())save(dst/(name+".f32"),buf);if(std::string(r)!="F8"){save(dst/"gate.f32",v->rawGate);save(dst/"up.f32",v->rawUp);require(finite(v->rawGate)&&finite(v->rawUp),"nonfinite raw projection");}
 [cases addObject:@{@"step":@(step),@"route":@(r),@"clean_completed":@(c.status==MTLCommandBufferStatusCompleted),@"probed_completed":@(p.status==MTLCommandBufferStatusCompleted),@"probe_fidelity_pass":@(fidelity),@"clean_dispatches":@(e.count(r)),@"probed_extra_copy_dispatches":@(std::string(r)=="F8"?0:2)}];b.emplace(r,std::move(v));}
 auto compare=[&](const std::string&actual,const std::string&reference){NSMutableDictionary*m=[NSMutableDictionary dictionary];bool pass=true;for(auto&[name,buf]:b.at(actual)->outputs()){auto x=metrics(buf,b.at(reference)->outputs().at(name));m[@(name.c_str())]=x;pass&=[x[@"bitwise_pass"]boolValue];}all&=pass;[cases addObject:@{@"step":@(step),@"comparison":@( (actual+"-vs-"+reference).c_str()),@"all_rows_bitwise_pass":@(pass),@"metrics":m}];};compare("G","S");compare("K","Kref");compare("F8","F8ref");
 for(auto r:{"S","G","K","F8"}){auto&v=*b.at(r);auto&raw=*b.at(std::string(r)=="F8"?"F8ref":r);auto a=local64(v.activation,raw.rawGate,raw.rawUp,in.gamma,false),n=local64(v.norm,v.activation,v.activation,in.gamma,true);bool pass=[a[@"pass"]boolValue]&&[n[@"pass"]boolValue];all&=pass;[cases addObject:@{@"step":@(step),@"route":@(r),@"local_post_norm_fp64_pass":@(pass),@"activation":a,@"weighted_norm":n,@"raw_projection_reference":std::string(r)=="F8"?@"same-input split C8 replay":@"actual probed route G/U"}];}
 auto actual=fixture/("step-"+std::to_string(step))/"layer-0";NSMutableDictionary*m=[NSMutableDictionary dictionary];for(auto&[name,buf]:b.at("K")->outputs()){auto ref=load(e.device(),actual/(name+".f32"),buf.length);auto q=metrics(buf,ref);m[@(name.c_str())]=q;all&=[q[@"bitwise_pass"]boolValue];}for(auto name:{"gate","up"}){auto buf=std::string(name)=="gate"?b.at("K")->rawGate:b.at("K")->rawUp;auto ref=load(e.device(),actual/(std::string(name)+".f32"),27648);auto q=metrics(buf,ref);m[@(name)]=q;all&=[q[@"bitwise_pass"]boolValue];}[cases addObject:@{@"step":@(step),@"comparison":@"K-independent-helper-vs-actual-model-graph",@"metrics":m}];
 }}json(out/"qualification.json",@{@"local_research_pass":@(all),@"integration_parity_reference":@"GvsS,KvsindependentK0,F8vssplitC8; actualgraphK checked",@"full_chain_fp64_pass":[NSNull null],@"model_output_pass":[NSNull null],@"model_quality_tested":@NO,@"CPU_processing_success":@YES,@"identity_sha256":hashes,@"records":cases,@"device":e.device().name,@"pipelines":e.metadata(),@"threshold":@{@"abs":@(2e-4),@"relative":@(2e-5)},@"scope":@"layer0 steps1/16/32 on identical actual graph K W/X; introduced-stage checks only"});return all?0:1;}

struct Sample{double gpu,start,end,cpu,wall;std::string before,after;bool lowBefore,lowAfter;};
static Sample sample(Engine&e,const std::string&r,Inputs&i,Buffers&b){auto before=thermal();bool low=NSProcessInfo.processInfo.lowPowerModeEnabled;auto wall=Clock::now();auto c=[e.queue()commandBuffer];c.label=@(("operator-timing-"+r).c_str());auto cpu=Clock::now();e.encode(c,r,i,b,false);double encode=us(cpu);complete(c);double w=us(wall),start=c.GPUStartTime,end=c.GPUEndTime;require(end>start&&start>0,"invalid completed GPU timestamps");return {(end-start)*1e6,start,end,encode,w,before,thermal(),low,NSProcessInfo.processInfo.lowPowerModeEnabled};}
static int benchmark(Engine&e,const fs::path&fixture,const fs::path&shader,const fs::path&out){auto gate=readJSON(out/"qualification.json");require([gate[@"local_research_pass"]boolValue],"local research qualification failed");require([gate[@"identity_sha256"]isEqual:identities(fixture,shader)],"qualification inputs/shaders changed");auto perf=out/"performance";require(!fs::exists(perf),"refuse existing performance");fs::create_directories(perf);Inputs in(e.device(),fixture,16);Buffers b(e.device());std::ofstream csv(perf/"samples.csv");csv<<std::setprecision(17)<<"comparison,round,pair,first,a_route,b_route,a_gpu_us,b_gpu_us,b_minus_a_gpu_us,a_gpu_start_s,a_gpu_end_s,b_gpu_start_s,b_gpu_end_s,a_cpu_encode_us,b_cpu_encode_us,a_dispatch_wall_us,b_dispatch_wall_us,a_thermal_before,a_thermal_after,b_thermal_before,b_thermal_after,a_low_power,b_low_power\n";std::vector<std::pair<std::string,std::string>>contrasts={{"S","S"},{"S","G"},{"S","K"},{"S","F8"},{"G","K"}};size_t count=0;NSMutableArray*schedule=[NSMutableArray array];for(int round=1;round<=3;++round){auto order=contrasts;std::rotate(order.begin(),order.begin()+(round-1),order.end());for(const auto&[a,z]:order){for(int w=0;w<30;++w){sample(e,a,in,b);sample(e,z,in,b);}struct Pair{Sample a,b;bool ab;};std::vector<Pair>samples;samples.reserve(201);for(int p=0;p<201;++p){Sample x,y;bool ab=(p+round)%2==0;if(ab){x=sample(e,a,in,b);y=sample(e,z,in,b);}else{y=sample(e,z,in,b);x=sample(e,a,in,b);}samples.push_back({x,y,ab});}for(size_t p=0;p<samples.size();++p){const auto&v=samples[p];const auto&x=v.a;const auto&y=v.b;csv<<a<<'-'<<z<<','<<round<<','<<p<<','<<(v.ab?"AB":"BA")<<','<<a<<','<<z<<','<<x.gpu<<','<<y.gpu<<','<<y.gpu-x.gpu<<','<<x.start<<','<<x.end<<','<<y.start<<','<<y.end<<','<<x.cpu<<','<<y.cpu<<','<<x.wall<<','<<y.wall<<','<<x.before<<','<<x.after<<','<<y.before<<','<<y.after<<','<<(x.lowBefore||x.lowAfter)<<','<<(y.lowBefore||y.lowAfter)<<'\n';}count+=samples.size();[schedule addObject:@{@"round":@(round),@"A":@(a.c_str()),@"B":@(z.c_str()),@"pairs":@201,@"warmups_per_path":@30}];}}require(bool(csv),"timing CSV write");csv.close();json(perf/"execution.json",@{@"execution_success":@YES,@"actual_pairs":@(count),@"command_buffers":@(count*2),@"capture_during_timing":@NO,@"readback_during_timing":@NO,@"diagnostic_logging_during_timing":@NO,@"GPU_interval":@"GPUEndTime-GPUStartTime aftercompletion; one wholeFFN sequence perCB",@"CPU_encode_interval":@"encoder init through dispatches/end/free, excludes CBcreation/commit/wait",@"wall_interval":@"CBcreation through waitUntilCompleted",@"scope":@"standalone layer0 step16 FFN normalizedX through stockdown; not fullmodeldecode",@"schedule":schedule,@"device":e.device().name,@"pipeline_metadata":e.metadata(),@"qualification_sha256":@(hashFile(out/"qualification.json").c_str()),@"samples_sha256":@(hashFile(perf/"samples.csv").c_str()),@"clock_period_ns":@(double(Clock::period::num)*1e9/Clock::period::den)});return 0;}
}

extern "C" int bitnet_run_iphone_operator(const char*fixture,const char*shader,const char*out,const char*mode){@autoreleasepool{try{using namespace bitnet_iphone_operator;require(fixture&&shader&&out&&mode,"null operator argument");Engine e(shader);std::string m=mode;if(m=="reference")return reference(e,fixture,shader,out);if(m=="verify")return verify(e,fixture,shader,out);if(m=="benchmark")return benchmark(e,fixture,shader,out);throw std::runtime_error("operator mode must be reference, verify or benchmark");}catch(const std::exception&e){std::fprintf(stderr,"IPHONE_OPERATOR_ERROR %s\n",e.what());if(out){NSError*err=nil;NSString*p=@((std::string(out)+"/operator-error.txt").c_str());[NSFileManager.defaultManager createDirectoryAtPath:p.stringByDeletingLastPathComponent withIntermediateDirectories:YES attributes:nil error:&err];[@(e.what())writeToFile:p atomically:YES encoding:NSUTF8StringEncoding error:&err];}return 3;}}}
